import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './PersonnelTable.css'

const PersonnelTable = () => {
  const [personnels, setPersonnels] = useState([]);
  const [newPersonnel, setNewPersonnel] = useState({
    first_name: '', last_name: '', rank: '', role_id: '', unit_id: '', squad_id: '', phone_number: '', email: ''
  });
  const [editingPersonnel, setEditingPersonnel] = useState(null);

  useEffect(() => {
    fetchPersonnels();
  }, []);

  const fetchPersonnels = async () => {
    try {
      const response = await axios.get('/api/personnels');
      setPersonnels(response.data);
    } catch (error) {
      console.error('Error fetching personnels:', error);
    }
  };

  const handleDelete = async (id) => {
    try {
      await axios.delete(`/api/personnels/${id}`);
      fetchPersonnels();
    } catch (error) {
      console.error('Error deleting personnel:', error);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      if (editingPersonnel) {
        // Update Personnel
        await axios.put(`/api/personnels/${editingPersonnel.id}`, newPersonnel);
        setEditingPersonnel(null);
      } else {
        // Add Personnel
        await axios.post('/api/personnels', newPersonnel);
      }
      setNewPersonnel({
        first_name: '', last_name: '', rank: '', role_id: '', unit_id: '', squad_id: '', phone_number: '', email: ''
      });
      fetchPersonnels();
    } catch (error) {
      console.error('Error adding/updating personnel:', error);
    }
  };

  const handleEdit = (personnel) => {
    setEditingPersonnel(personnel);
    setNewPersonnel(personnel);
  };

  return (
    <div>
      <h1>Personnel Management</h1>
      <form onSubmit={handleSubmit}>
        <h2>{editingPersonnel ? 'Edit' : 'Add'} Personnel</h2>
        <input
          type="text"
          placeholder="First Name"
          value={newPersonnel.first_name}
          onChange={(e) => setNewPersonnel({ ...newPersonnel, first_name: e.target.value })}
          required
        />
        <input
          type="text"
          placeholder="Last Name"
          value={newPersonnel.last_name}
          onChange={(e) => setNewPersonnel({ ...newPersonnel, last_name: e.target.value })}
          required
        />
        <input
          type="text"
          placeholder="Rank"
          value={newPersonnel.rank}
          onChange={(e) => setNewPersonnel({ ...newPersonnel, rank: e.target.value })}
          required
        />
        <input
          type="number"
          placeholder="Role ID"
          value={newPersonnel.role_id}
          onChange={(e) => setNewPersonnel({ ...newPersonnel, role_id: e.target.value })}
          required
        />
        <input
          type="number"
          placeholder="Unit ID"
          value={newPersonnel.unit_id}
          onChange={(e) => setNewPersonnel({ ...newPersonnel, unit_id: e.target.value })}
          required
        />
        <input
          type="number"
          placeholder="Squad ID"
          value={newPersonnel.squad_id}
          onChange={(e) => setNewPersonnel({ ...newPersonnel, squad_id: e.target.value })}
          required
        />
        <input
          type="text"
          placeholder="Phone Number"
          value={newPersonnel.phone_number}
          onChange={(e) => setNewPersonnel({ ...newPersonnel, phone_number: e.target.value })}
          required
        />
        <input
          type="email"
          placeholder="Email"
          value={newPersonnel.email}
          onChange={(e) => setNewPersonnel({ ...newPersonnel, email: e.target.value })}
          required
        />
        <button type="submit">{editingPersonnel ? 'Update' : 'Add'} Personnel</button>
      </form>

      <table>
        <thead>
          <tr>
            <th>First Name</th>
            <th>Last Name</th>
            <th>Rank</th>
            <th>Role ID</th>
            <th>Unit ID</th>
            <th>Squad ID</th>
            <th>Phone Number</th>
            <th>Email</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {personnels.map((personnel) => (
            <tr key={personnel.id}>
              <td>{personnel.first_name}</td>
              <td>{personnel.last_name}</td>
              <td>{personnel.rank}</td>
              <td>{personnel.role_id}</td>
              <td>{personnel.unit_id}</td>
              <td>{personnel.squad_id}</td>
              <td>{personnel.phone_number}</td>
              <td>{personnel.email}</td>
              <td>
                <button onClick={() => handleEdit(personnel)}>Edit</button>
                <button onClick={() => handleDelete(personnel.id)}>Delete</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default PersonnelTable;
